mapper.select:
        select
        c1.C_Name_History as pecConstructionUnitNameHistory,
        c1.C_Name as pecConstructionUnitName,
        c2.C_Name as pecUnitName,
        sd.D_Name as pecDepartmentName,
        c1.C_Abbreviation as pecConstructionAbbName,
        f.file_relation_id as fileRelationId,
        
        from  Pe_Info_Collect pec
        left join  Sys_Company c1 on pec.pec_Construction_Unit_Id=c1.C_Id
        left join  Sys_Company c2 on pec.Pec_Unit_Id=c2.C_Id
        left join  Sys_Department sd on pec.Pec_Department=sd.D_Id
        left join  Sys_File f on f.FileID=pec.pec_Id
        
            
                and pec.Te_Id = #{params.teId}
            
            
                and pec.Pec_Year=#{params.pecYear}
            
            
                and pec.Pec_Quarter=#{params.pecQuarter}
            
            
                and pec.Pec_Type=#{params.pecType}
            
            
                and pec.pec_Construction_Unit_Id=#{params.pecConstructionUnitId}
            
            
                and pec.Pec_Unit_Id=#{params.pecUnitId}
            
            
                and pec.Pec_Uname=#{params.pecUname}
            
            
                
                    
                        and  likeCname(#{params.pecConstructionUnitName},c1.C_Id)=true
                    
                    
                        and  c1.C_Name  like concat('%',#{params.pecConstructionUnitName},'%')
                    
                
            
            
                and pec.Pec_Department=#{params.pecDepartment}
            

        
        
            order by pec.${params.sortFiled} ${params.sortType}
        
        
            order by pec.pec_Date desc
        
        limit #{params.start},#{params.size}

select
count(1)
from  Pe_Info_Collect pec
left join  Sys_Company c1 on pec.pec_Construction_Unit_Id=c1.C_Id
left join  Sys_Department sd on pec.Pec_Unit_Id=sd.D_Id

    
        and pec.Te_Id = #{params.teId}
    
    
        and pec.Pec_Year=#{params.pecYear}
    
    
        and pec.Pec_Quarter=#{params.pecQuarter}
    
    
        and pec.Pec_Type=#{params.pecType}
    
    
        and pec.pec_Construction_Unit_Id=#{params.pecConstructionUnitId}
    
    
        and pec.Pec_Unit_Id=#{params.pecUnitId}
    
    
        and pec.Pec_Uname=#{params.pecUname}
    
    
        and  c1.C_Name  like concat('%',#{params.pecConstructionUnitName},'%')
    
    
        and pec.Pec_Department=#{params.pecDepartment}
